@page "/products"
@rendermode InteractiveServer
@inject ProductService Products

<input @bind="query" placeholder="Search" />

<ul>
    @foreach (var product in Filtered)
    {
        <li>@product.Name</li>
    }
</ul>

@code {
    private string query = "";
    private List<Product> all = [];

    protected override async Task OnInitializedAsync()
    {
        all = await Products.ListAsync();
    }

    private IEnumerable<Product> Filtered =>
        all.Where(p => p.Name.Contains(query, StringComparison.OrdinalIgnoreCase));
}
